// Every block below is REFUSED at load. None is a silent clamp. All targets
// are UNSEALED families, so each refusal shown fires for the stated reason —
// against a sealed family the whole overlay would be refused before any of
// these rules were even consulted.

// 1. Lowering a floor — would let a contributor buy confidence they did not
//    earn. The shipped APH_ACT_FINANCIAL base floor is t0_signals >= 985.
classifiers "APH_ACT_FINANCIAL" {
  escalate t0_signals >= 700    // base is 985. REFUSED.
}

// 2. Adding a rung — would route inputs to a tier the author never
//    sanctioned, which can move user content to a different locality.
//    The shipped base declares t0/t1/t3 and deliberately no cloud rung.
classifiers "APH_ACT_FINANCIAL" {
  escalate t4_cloud >= 800      // base declared no cloud rung. REFUSED.
}

// 3. Relaxing privacy locality — classifier inputs carry user content.
//    APH_JURISDICTION inherits the default local_only.
classifiers "APH_JURISDICTION" {
  privacy_locality = "cloud_ok" // base is local_only. REFUSED.
}

// 4. Relaxing fail posture — unavailability must never grant a capability.
//    APH_URGENCY inherits the default fail_closed.
classifiers "APH_URGENCY" {
  fail_posture = "fail_open"    // base is fail_closed. REFUSED.
}

// 5. Colliding a label name — the name is a wire value someone already read.
//    TIME_ACCEPTED is a real, shipped APH_ACT_SCHEDULING label.
classifiers "APH_ACT_SCHEDULING" {
  labels {
    TIME_ACCEPTED {
      description = "redefined to mean something else"  // REFUSED.
      examples    = ["a", "b", "c"]
    }
  }
}
